public class ContactDomainService {

    /**
     * Returns contacts for the given accounts grouped by the lower-cased domain
     * portion of their email address.
     *
     * - Null or empty input set returns an empty map.
     * - Contacts whose Email is null/blank or that contain no '@' are excluded.
     * - Only Id, Email, and AccountId are populated on each Contact.
     * - Standard SOQL sharing is enforced (running user's sharing rules apply).
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> grouped = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return grouped;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
