    public class SearchException extends Exception {
    }

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {

        // --- Validate maxRows ---
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be an integer between 1 and 200');
        }

        // --- Validate and resolve object (case-insensitive) ---
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required');
        }
        String resolvedObjectName = resolveObjectName(objectApiName);
        if (resolvedObjectName == null) {
            throw new SearchException('Object does not exist or is not accessible: ' + objectApiName);
        }
        Map<String, Schema.FieldDescribe> fieldMap = Schema.getGlobalDescribe().get(resolvedObjectName).getFields();

        // --- Validate fields list ---
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list must not be null or empty');
        }

        // Resolve and validate each requested field
        List<String> selectParts = new List<String>{ 'Id' };
        Set<String> selectedFieldsSet = new Set<String>{ 'Id' };
        for (String field : fields) {
            if (String.isBlank(field)) {
                throw new SearchException('Field name cannot be blank');
            }
            String resolvedField = resolveFieldName(fieldMap, field);
            if (resolvedField == null) {
                throw new SearchException('Field not found on object ' + resolvedObjectName + ': ' + field);
            }
            if (!fieldMap.get(resolvedField).isAccessible()) {
                throw new SearchException('User does not have read access to field: ' + field);
            }
            if (!selectedFieldsSet.contains(resolvedField)) {
                selectParts.add(resolvedField);
                selectedFieldsSet.add(resolvedField);
            }
        }

        // --- Build WHERE clause from filters ---
        List<String> whereParts = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter field name cannot be blank');
                }
                String resolvedFilterField = resolveFieldName(fieldMap, filterKey);
                if (resolvedFilterField == null) {
                    throw new SearchException('Filter field not found on object ' + resolvedObjectName + ': ' + filterKey);
                }
                Schema.FieldDescribe filterFd = fieldMap.get(resolvedFilterField);
                if (!filterFd.isAccessible()) {
                    throw new SearchException('User does not have read access to filter field: ' + filterKey);
                }
                if (!isFilterable(filterFd)) {
                    throw new SearchException('Field cannot be filtered: ' + filterKey);
                }
                whereParts.add(resolvedFilterField + ' = ' + formatValue(filters.get(filterKey)));
            }
        }

        // --- Validate and resolve ORDER BY ---
        String resolvedOrderBy = null;
        if (!String.isBlank(orderByField)) {
            resolvedOrderBy = resolveFieldName(fieldMap, orderByField);
            if (resolvedOrderBy == null) {
                throw new SearchException('Order-by field not found on object ' + resolvedObjectName + ': ' + orderByField);
            }
            Schema.FieldDescribe orderFd = fieldMap.get(resolvedOrderBy);
            if (!orderFd.isAccessible()) {
