@isTest
private class ShippingCostCalculatorTest {

    private static void assertQuote(Decimal weightKg, String zone, Boolean express, Decimal orderValue, Decimal expected) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        Assert.assertEquals(expected, actual,
            'quote(' + weightKg + ', ' + zone + ', ' + express + ', ' + orderValue + ')');
    }

    private static void assertShippingException(Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        try {
            ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
            Assert.fail('Expected ShippingException for quote(' + weightKg + ', ' + zone + ', ' + express + ', ' + orderValue + ')');
        } catch (ShippingCostCalculator.ShippingException e) {
            // expected
        }
    }

    // ─── Weight validation ───────────────────────────────────────────────

    @isTest
    static void testWeightValidation() {
        assertShippingException(null, 'DOMESTIC', false, 0);
        assertShippingException(0, 'DOMESTIC', false, 0);
        assertShippingException(-1, 'DOMESTIC', false, 0);
        assertShippingException(-0.001, 'DOMESTIC', false, 0);
    }

    @isTest
    static void testTinyPositiveWeight() {
        assertQuote(0.001, 'DOMESTIC', false, 0, 5.00);
    }

    // ─── Weight bracket boundaries (DOMESTIC, standard) ──────────────────

    @isTest
    static void testWeightBoundaries() {
        // Bracket 1: <= 1 kg → 5.00
        assertQuote(0.5, 'DOMESTIC', false, 0, 5.00);
        assertQuote(1, 'DOMESTIC', false, 0, 5.00);       // boundary
        assertQuote(1.01, 'DOMESTIC', false, 0, 9.50);    // just above

        // Bracket 2: <= 5 kg → 9.50
        assertQuote(5, 'DOMESTIC', false, 0, 9.50);       // boundary
        assertQuote(5.01, 'DOMESTIC', false, 0, 18.00);   // just above

        // Bracket 3: <= 20 kg → 18.00
        assertQuote(20, 'DOMESTIC', false, 0, 18.00);     // boundary
        assertQuote(20.01, 'DOMESTIC', false, 0, 18.75);  // just above

        // Bracket 4: > 20 kg
        assertQuote(20.1, 'DOMESTIC', false, 0, 18.75);   // documented
        assertQuote(22, 'DOMESTIC', false, 0, 19.50);     // documented
        assertQuote(25, 'DOMESTIC', false, 0, 21.75);
        assertQuote(30, 'DOMESTIC', false, 0, 25.50);
    }

    // ─── Started-kilogram (CEILING) above 20 kg ─────────────────────────

    @isTest
    static void testStartedKilogramCeiling() {
        // CEILING(0.1)=1, CEILING(0.5)=1, CEILING(0.99)=1, CEILING(1)=1
        assertQuote(20.1, 'DOMESTIC', false, 0, 18.75);
        assertQuote(20.5, 'DOMESTIC', false, 0, 18.75);
        assertQuote(20.99, 'DOMESTIC', false, 0, 18.75);
        assertQuote(21, 'DOMESTIC', false, 0, 18.75);
        // CEILING(1.01)=2
        assertQuote(21.01, 'DOMESTIC', false, 0, 19.50);
        // CEILING(2)=2
        assertQuote(22, 'DOMESTIC', false, 0, 19.50);
        // CEILING(5)=5
        assertQuote(25, 'DOMESTIC', false, 0, 21.75);
        // CEILING(10)=10
        assertQuote(30, 'DOMESTIC', false, 0, 25.50);
    }

    // ─── Zone factors ────────────────────────────────────────────────────

    @isTest
    static void testZoneFactors() {
        // DOMESTIC ×1.0
        assertQuote(1, 'DOMESTIC', false, 0, 5.00);
        assertQuote(5, 'DOMESTIC', false, 0, 9.50);
        assertQuote(20, 'DOMESTIC', false, 0, 18.00);

        // EU ×1.4
        assertQuote(1, 'EU', false, 0, 7.00);
        assertQuote(5, 'EU', false, 0, 13.30);
        assertQuote(20, 'EU', false, 0, 25.20);
        assertQuote(22, 'EU', false, 0, 27.30);

        // WORLD ×2.2
        assertQuote(1, 'WORLD', false, 0, 11.00);
        assertQuote(5, 'WORLD', false, 0, 20.90);
        assertQuote(20, 'WORLD', false, 0, 39.60);
        assertQuote(22, 'WORLD', false, 0, 42.90);
    }

    @isTest
    static void testZoneCaseInsensitive() {
        assertQuote(1, 'domestic', false, 0, 5.00);
        assertQuote(1, 'Domestic', false, 0, 5.00);
        assertQuote(1, 'DOMESTIC', false, 0, 5.00);
        assertQuote(1, 'eu', false, 0, 7.00);
        assertQuote(1, 'Eu', false, 0, 7.00);
        assertQuote(1, 'EU', false, 0, 7.00);
        assertQuote(1, 'world', false, 0, 11.00);
        assertQuote(1, 'World', false, 0, 11.00);
        assertQuote(1, 'WORLD', false, 0, 11.00);
    }

    // ─── Invalid / null zone ─────────────────────────────────────────────

    @isTest
    static void testInvalidZone() {
        assertShippingException(1, null, false, 0);
        assertShippingException(1, '', false, 0);
        assertShippingException(1, 'MARS', false, 0);
        assertShippingException(1, 'LOCAL', false, 0);
        assertShippingException(1, 'domestic ', false, 0);
    }

    // ─── Express delivery ────────────────────────────────────────────────

    @isTest
    static void testExpress() {
        // Express ×1.5
        assertQuote(1, 'DOMESTIC', true, 0, 7.50);
        assertQuote(1, 'EU', true, 0, 10.50);
        assertQuote(1, 'WORLD', true, 0, 16.50);
        assertQuote(5, 'EU', true, 0, 19.95);
        assertQuote(20, 'WORLD', true, 0, 59.40);

        // Explicit false
        assertQuote(1, 'DOMESTIC', false, 0, 5.00);
        assertQuote(1, 'EU', false, 0, 7.00);

        // Null express = standard
        assertQuote(1, 'DOMESTIC', null, 0, 5.00);
        assertQuote(1, 'EU', null, 0, 7.00);
        assertQuote(1, 'WORLD', null, 0, 11.00);
    }

    // ─── Free shipping (DOMESTIC + standard + orderValue >= 100) ────────

    @isTest
    static void testFreeShipping() {
        // Exactly 100 → free
        assertQuote(1, 'DOMESTIC', false, 100.00, 0);
        // Above 100 → free
        assertQuote(1, 'DOMESTIC', false, 150.00, 0);
        assertQuote(25, 'DOMESTIC', false, 500.00, 0);
        // Below 100 → not free
        assertQuote(1, 'DOMESTIC', false, 99.99, 5.00);
        assertQuote(1, 'DOMESTIC', false, 0, 5.00);
        // Express → not free
        assertQuote(1, 'DOMESTIC', true, 200.00, 7.50);
        // Null express (= standard) → free
        assertQuote(1, 'DOMESTIC', null, 100.00, 0);
        // EU → not free
        assertQuote(1, 'EU', false, 200.00, 7.00);
        // WORLD → not free
        assertQuote(1, 'WORLD', false, 200.00, 11.00);
        // Null orderValue → not free
        assertQuote(1, 'DOMESTIC', false, null, 5.00);
    }

    // ─── Rounding (HALF_UP to 2 dp) ──────────────────────────────────────

    @isTest
    static void testRounding() {
        // 21 kg DOMESTIC express: 18.75 × 1.0 × 1.5 = 28.125 → 28.13
        assertQuote(21, 'DOMESTIC', true, null, 28.13);
        // 20.5 kg EU express: 18.75 × 1.4 × 1.5 = 39.375 → 39.38
        assertQuote(20.5, 'EU', true, 0, 39.38);
        // 20.5 kg WORLD express: 18.75 × 2.2 × 1.5 = 61.875 → 61.88
        assertQuote(20.5, 'WORLD', true, 0, 61.88);
        // Values that are already exact (no rounding needed)
        assertQuote(1, 'EU', false, 0, 7.00);
        assertQuote(5, 'WORLD', false, 0, 20.90);
        assertQuote(20, 'EU', false, 0, 25.20);
    }

    // ─── Combined scenarios ──────────────────────────────────────────────

    @isTest
    static void testCombinedScenarios() {
        // Large weight, WORLD, express
        assertQuote(30, 'WORLD', true, 0, 84.15);   // 25.50 × 2.2 × 1.5 = 84.15
        // EU, express, moderate weight
        assertQuote(12, 'EU', true, 0, 37.80);      // 18.00 × 1.4 × 1.5 = 37.80
        // DOMESTIC, 0.5 kg, express
        assertQuote(0.5, 'DOMESTIC', true, 0, 7.50);
        // Just over 20, EU, no express
        assertQuote(20.1, 'EU', false, 0, 26.25);   // 18.75 × 1.4 = 26.25
    }
}
