        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Default LeadSource to 'Web' where blank
        for (Lead lead : leads) {
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }

        // Identify in-call duplicate emails (case-insensitive, trimmed)
        Set<String> seenEmails = new Set<String>();
        List<Lead> toInsert = new List<Lead>();
        List<Integer> originalIndices = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];
            String email = lead.Email;

            if (!String.isBlank(email)) {
                String normalized = email.trim().toLowerCase();
                if (seenEmails.contains(normalized)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalized);
                    continue;
                }
                seenEmails.add(normalized);
            }

            toInsert.add(lead);
            originalIndices.add(i);
        }

        // Single DML pass: partial-success insert respecting the running user's sharing
        for (Integer j = 0; j < toInsert.size(); j++) {
            Database.SaveResult sr = Database.insert(toInsert[j], false);
            Integer originalIdx = originalIndices[j];

            if (sr.isSuccess()) {
                result.insertedIds.add(toInsert[j].Id);
                result.successCount++;
