public inherited sharing class Application {
    public static fflib_Application.UnitOfWorkFactory UnitOfWork { get; private set; }
    public static fflib_Application.ServiceFactory Service { get; private set; }
    public static fflib_Application.SelectorFactory Selector { get; private set; }
    public static fflib_Application.DomainFactory Domain { get; private set; }

    static {
        // ── Unit of Work ──────────────────────────────────────────────
        UnitOfWork = new fflib_Application.UnitOfWorkFactory();

        // Register the SObject types that the UOW will manage
        UnitOfWork.addSObjectType(Account.SObjectType);
        UnitOfWork.addSObjectType(Contact.SObjectType);
        UnitOfWork.addSObjectType(Opportunity.SObjectType);
        UnitOfWork.addSObjectType(OpportunityContactRole.SObjectType);

        // Parent-child relationships (parent, child, foreign-key field on child)
        // Account → Contact
        UnitOfWork.addParentChild(Account.SObjectType, Contact.SObjectType, Contact.AccountId);
        // Account → Opportunity
        UnitOfWork.addParentChild(Account.SObjectType, Opportunity.SObjectType, Opportunity.AccountId);
        // Opportunity → OpportunityContactRole
        UnitOfWork.addParentChild(Opportunity.SObjectType, OpportunityContactRole.SObjectType, OpportunityContactRole.OpportunityId);
        // Contact → OpportunityContactRole
        UnitOfWork.addParentChild(Contact.SObjectType, OpportunityContactRole.SObjectType, OpportunityContactRole.ContactId);

        // ── Service ───────────────────────────────────────────────────
        Service = new fflib_Application.ServiceFactory();
        Service.addImplementation(IAccountsService.class, AccountsServiceImpl.class);

        // ── Selector ──────────────────────────────────────────────────
        Selector = new fflib_Application.SelectorFactory();
        Selector.add(Account.SObjectType, AccountsSelector.class);
        Selector.add(Contact.SObjectType, ContactsSelector.class);

        // ── Domain ────────────────────────────────────────────────────
        Domain = new fflib_Application.DomainFactory();
        Domain.add(Account.SObjectType, Accounts.class, new Accounts.Constructor());
    }
