        return new Constructor();
    }

    public override void validateInsert() {
        for (Opportunity opp : (List<Opportunity>) Trigger.new) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, 'Amount');
            }
        }
    }

    public override void validateUpdate() {
        for (Opportunity opp : (List<Opportunity>) Trigger.new) {
            // Rule 1: Amount must not be negative
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, 'Amount');
            }

            // Rule 2: Amount cannot change on an already-won opportunity
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
            if (oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', opp, 'Amount');
            }
        }
    }
}
