        super.onInsert();
        validateAmountNotNegative();
    }

    public virtual void onUpdate() {
        super.onUpdate();
        validateAmountNotNegative();
        validateWonOpportunityAmountUnchanged();
    }

    private void validateAmountNotNegative() {
        List<Opportunity> opportunities = (List<Opportunity>) getRecordList();
        for (Opportunity opportunity : opportunities) {
            if (opportunity.Amount != null && opportunity.Amount < 0) {
                error('Amount cannot be negative.', opportunity, Opportunity.Amount);
            }
        }
    }

    private void validateWonOpportunityAmountUnchanged() {
        List<Opportunity> opportunities = (List<Opportunity>) getRecordList();
        Map<Id, Opportunity> oldOpportunityMap = (Map<Id, Opportunity>) getOldRecordMap();
        for (Opportunity opportunity : opportunities) {
            Opportunity oldOpportunity = oldOpportunityMap.get(opportunity.Id);
            if (oldOpportunity != null
                    && oldOpportunity.StageName == 'Closed Won'
                    && opportunity.Amount != oldOpportunity.Amount) {
                error('Amount cannot change on a won opportunity.', opportunity, Opportunity.Amount);
            }
        }
    }
