    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory qf = getSObjectQueryFactory();

        // Add the parent Account relationship so Account.Name is available on each row.
        qf.addFields(Opportunity.Account);

        // Open opportunities belonging to the specified accounts.
        qf.setWhere('IsClosed = false AND AccountId IN :accountIds');

        // Highest Amount first; SOQL places NULL amounts last by default.
        // Ties (including among NULL-amount rows) broken by CloseDate ascending.
        qf.setOrder('Amount DESC, CloseDate ASC');

        qf.setLimit(maxRecords);

        return (List<Opportunity>) qf.select();
    }
}
