public class CaseEscalationService {
    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Escalation reason is required.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        if (cases == null || cases.isEmpty()) {
            return;
        }

        List<Case> casesToEscalate = new List<Case>();

        for (Case currentCase : cases) {
            if (String.equals(currentCase.Status, 'Closed') || currentCase.IsEscalated == true) {
                continue;
            }

            casesToEscalate.add(currentCase);
        }

        if (casesToEscalate.isEmpty()) {
            return;
        }

        fflib_IUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();
        Date activityDate = Date.today().addDays(1);

        for (Case currentCase : casesToEscalate) {
            currentCase.IsEscalated = true;
            currentCase.Priority = 'High';
            unitOfWork.registerDirty(currentCase);

            Task escalationTask = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = currentCase.Id,
                OwnerId = currentCase.OwnerId,
                ActivityDate = activityDate,
                Priority = 'High'
            );
            unitOfWork.registerNew(escalationTask);
        }

        unitOfWork.commitWork();
    }

    public class EscalationException extends Exception {
        public EscalationException(String message) {
            super(message);
        }
    }
}
