public class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                opp.StageName = 'Closed Won';
                opp.CloseDate = Date.today();
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        fflib_Application.UnitOfWork unitOfWork = Application.UnitOfWork.newInstance();
        unitOfWork.begin();

        // Stage the DML – fflib queues it and only executes on commit
        unitOfWork.saveSObjects(toClose);

        // Stage the platform events – fflib queues them and only publishes
        // after the DML has committed successfully inside commit()
        List<SObject> events = new List<SObject>();
        for (Opportunity opp : toClose) {
            Deal_Won__e event = new Deal_Won__e();
            event.Opportunity_Id__c = String.valueOf(opp.Id);
            event.Amount__c = opp.Amount;
            events.add(event);
        }
        unitOfWork.publishEvents(events);

        // Single commit: fflib executes all DML first, then publishes events.
        // If the DML throws, the exception propagates and events are never
        // published.
        unitOfWork.commit();

        return toClose.size();
    }
}
