public class PipelineSummary {

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        List<String> stages = new List<String>{
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String stage : stages) {
            List<AggregateResult> rows = [
                SELECT SUM(Amount) total
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            // An ungrouped aggregate always returns exactly one row; the
            // field is null when no rows match or every Amount is null.
            Decimal total = 0;
            if (!rows.isEmpty() && rows[0].get('total') != null) {
                total = (Decimal) rows[0].get('total');
            }

            result.put(stage, total);
        }

        return result;
    }
}
