    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Deduplicate and drop nulls so we don't build duplicate tasks or
        // pass a null into the IN clause.
        Set<Id> uniqueIds = new Set<Id>();
        for (Id id : opportunityIds) {
            if (id != null) {
                uniqueIds.add(id);
            }
        }
        if (uniqueIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Single SOQL – no injection risk with a bound list.
        List<Opportunity> opps = [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueIds
        ];
        if (opps.isEmpty()) {
            return failedOpportunityIds;
        }

        // Build the tasks in memory.  We keep a parallel list so we can map
        // each SaveResult back to the originating opportunity.
        List<Task>   tasksToInsert = new List<Task>();
        List<Id>     taskOppIds    = new List<Id>();
        Date         activityDate  = Date.today().addDays(7);

        for (Opportunity opp : opps) {
            tasksToInsert.add(new Task(
                WhatId       = opp.Id,
                OwnerId      = opp.OwnerId,
                Subject      = 'Follow up: ' + opp.Name,
                ActivityDate = activityDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
            taskOppIds.add(opp.Id);
        }

        // One bulk DML, continue-on-error: a validation-rule rejection on one
        // task does NOT prevent the others from being saved.  The SaveResult
        // list is in the same order as tasksToInsert, so we can zip them.
        List<Database.SaveResult> results = Database.insert(tasksToInsert, true);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedOpportunityIds.add(taskOppIds[i]);
            }
        }

        return failedOpportunityIds;
    }
}
