public class AccountRatingService {

    /**
     * Asynchronously recalculates the Rating on every account in the supplied set.
     *
     *   Hot  – at least one open opportunity with Amount >= 100,000
     *   Warm – open opportunities exist but none reach 100,000
     *   Cold – no open opportunities
     *
     * @param accountIds  Set of Account Ids to recalculate (max size is bounded
     *                    by the number of unique accounts in the triggering
     *                    transaction, well within @future payload limits).
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // One bulk query for all open opportunities belonging to the affected accounts.
        Map<Id, List<Opportunity>> oppsByAccount = new Map<Id, List<Opportunity>>();

        for (Opportunity opp : [
            SELECT Id, AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = FALSE
        ]) {
            if (oppsByAccount.containsKey(opp.AccountId)) {
                oppsByAccount.get(opp.AccountId).add(opp);
            } else {
                oppsByAccount.put(opp.AccountId, new List<Opportunity>{ opp });
            }
        }

        // Determine the correct Rating for each account.
        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : accountIds) {
            List<Opportunity> opps = oppsByAccount.get(accountId);
            String rating;

            if (opps == null || opps.isEmpty()) {
                rating = 'Cold';
            } else {
                Boolean hasHot = false;
                for (Opportunity opp : opps) {
                    if (opp.Amount != null && opp.Amount >= 100000) {
                        hasHot = true;
                        break;
                    }
                }
                rating = hasHot ? 'Hot' : 'Warm';
            }

            accountsToUpdate.add(new Account(Id = accountId, Rating = rating));
        }

        // One bulk DML statement for all account updates.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

