public class CaseSurveyJob implements Queueable {

    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        // Re-query the Case at execution time: the record may have
        // changed between enqueue and execution, and we only stored the Id.
        Case c = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        if (c == null || c.ContactId == null) {
            return;
        }

        Task task = new Task(
            WhatId      = c.Id,
            WhoId       = c.ContactId,
            Subject     = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status      = 'Not Started'
        );

        insert task;
    }
}
