import { LightningElement, wire, track } from 'lwc';
import { LightningMessageService, APPLICATION_SCOPE, MessageContext } from 'lightning/messageService';
import Account_Selected from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext)
    context;

    @track selectedRecordId;

    _messageSub;

    connectedCallback() {
        this.subscribeToMessage();
    }

    disconnectedCallback() {
        this.unsubscribeFromMessage();
    }

    subscribeToMessage() {
        // Ensure we never hold more than one subscription
        this.unsubscribeFromMessage();

        if (this.context?.data) {
            this._messageSub = LightningMessageService.subscribe(
                this.context.data,
                Account_Selected,
                (message) => {
                    this.handleMessage(message);
                },
                APPLICATION_SCOPE
            );
        }
    }

    unsubscribeFromMessage() {
        if (this._messageSub) {
            LightningMessageService.unsubscribe(this._messageSub);
            this._messageSub = null;
        }
    }

    handleMessage(message) {
        this.selectedRecordId = (message && message.recordId) ? message.recordId : null;
    }

    handleClear() {
        if (this.context?.data) {
            LightningMessageService.publish(
                this.context.data,
                Account_Selected,
                { recordId: null },
                APPLICATION_SCOPE
            );
        }
    }

    get showAccount() {
        return !!this.selectedRecordId;
    }

    get recordId() {
        return this.selectedRecordId;
    }
}
