import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { Confirm } from 'lightning/confirm';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Stage', fieldName: 'StageName', type: 'text' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities = [];

    get columns() {
        return COLUMNS;
    }

    get data() {
        return this.opportunities || [];
    }

    handleRowAction(event) {
        const { name } = event.detail.action;
        const row = event.detail.row;

        switch (name) {
            case 'view':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        objectApiName: 'Opportunity',
                        actionName: 'view'
                    }
                });
                break;

            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        objectApiName: 'Opportunity',
                        actionName: 'edit'
                    }
                });
                break;

            case 'delete':
                Confirm.show({
                    label: 'Confirm Delete',
                    message:
                        'Are you sure you want to delete this opportunity?',
                    confirmLabel: 'Delete',
                    cancelLabel: 'Cancel',
                    onConfirm: () => {
                        deleteRecord(row.Id)
                            .then(() => {
                                // Remove the row without mutating the parent's array
                                const updated = this.opportunities.filter(
                                    (opp) => opp.Id !== row.Id
                                );
                                this.opportunities = updated;

                                this.dispatchEvent(
                                    new ShowToastEvent({
                                        title: 'Opportunity deleted',
                                        message:
                                            'The opportunity was deleted successfully.',
                                        variant: 'success'
                                    })
                                );
                            })
                            .catch((error) => {
                                const message =
                                    error.body && error.body.message
                                        ? error.body.message
                                        : 'An unexpected error occurred.';

                                this.dispatchEvent(
                                    new ShowToastEvent({
                                        title: 'Delete failed',
                                        message: message,
                                        variant: 'error'
                                    })
                                );
                            });
                    },
                    onReject: () => {
                        // User cancelled – do nothing
                    }
                });
                break;

            default:
                break;
        }
    }
}
