import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** @type {{key: string, productName: string, quantity: number}[]} */
    @api lines = [];

    showErrors = false;

    handleButtonClick(event) {
        const action = event.target.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach((editor) => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;
        const values = [];

        // Validate every editor so that all invalid lines show their errors at once
        editors.forEach((editor) => {
            const isValid = editor.validate();
            if (!isValid) {
                allValid = false;
            }
            values.push(editor.getValue());
        });

        if (allValid) {
            this.showErrors = false;
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: values }
                })
            );
        } else {
            this.showErrors = true;
        }
    }
}
