import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasError = false;
    errorMessage;
    hasLoaded = false;

    _inFlight = false;
    _pollTimer = null;
    _visibilityHandler = null;

    connectedCallback() {
        this._loadStats();
        this._startPolling();
        this._visibilityHandler = () => this._onVisibilityChange();
        document.addEventListener('visibilitychange', this._visibilityHandler);
    }

    disconnectedCallback() {
        this._stopPolling();
        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }
        this._inFlight = false;
    }

    _startPolling() {
        this._stopPolling();
        this._pollTimer = setInterval(() => {
            this._loadStats();
        }, 60000);
    }

    _stopPolling() {
        if (this._pollTimer !== null) {
            clearInterval(this._pollTimer);
            this._pollTimer = null;
        }
    }

    _onVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this._loadStats();
            this._startPolling();
        }
    }

    async _loadStats() {
        if (this._inFlight) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }

        this._inFlight = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.hasError = false;
            this.errorMessage = undefined;
            this.hasLoaded = true;
        } catch (error) {
            this.hasError = true;
            this.errorMessage = error.body.message;
        } finally {
            this._inFlight = false;
        }
    }
}
