import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options;

    _value = '';

    @api
    get value() {
        return this._value;
    }

    @api
    set value(val) {
        this._value = val;
        this._updateActiveIndex();
    }

    activeIndex = 0;

    get activeDescendantId() {
        if (!this.options || this.options.length === 0) return '';
        return `option-${this.activeIndex}`;
    }

    get optionIds() {
        return (this.options || []).map((_, i) => `option-${i}`);
    }

    connectedCallback() {
        this._updateActiveIndex();
    }

    _updateActiveIndex() {
        if (!this.options || this.options.length === 0) {
            this.activeIndex = 0;
            return;
        }
        const idx = this.options.findIndex(o => o.value === this._value);
        this.activeIndex = idx >= 0 ? idx : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        if (!['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '].includes(key)) {
            return;
        }

        event.preventDefault();

        if (!this.options || this.options.length === 0) return;

        switch (key) {
            case 'ArrowDown':
                if (this.activeIndex < this.options.length - 1) {
                    this.activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                }
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = this.options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectOption(this.activeIndex);
                break;
        }
    }

    handleClick(event) {
        const value = event.currentTarget.dataset.value;
        const idx = this.options.findIndex(o => o.value === value);
        if (idx >= 0) {
            this.activeIndex = idx;
            this._selectOption(idx);
        }
    }

    _selectOption(index) {
        const opt = this.options[index];
        if (!opt) return;
        if (opt.value === this._value) return;

        this._value = opt.value;
        this.activeIndex = index;

        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: opt.value } })
        );
    }
}
