export default class StatusListbox extends LightningElement {
    @api label;

    @track _options = [];
    @track _value = '';
    @track _activeIndex = 0;

    @api
    get options() {
        return this._options;
    }

    @api
    set options(val) {
        this._options = val || [];
        this._updateActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    @api
    set value(val) {
        this._value = val;
        this._updateActiveIndex();
    }

    get optionItems() {
        return this._options.map((opt, i) => ({
            id: `statusListbox-option-${i}`,
            value: opt.value,
            label: opt.label,
            isSelected: opt.value === this._value
        }));
    }

    get activeDescendantId() {
        if (this._options.length === 0) {
            return '';
        }
        return `statusListbox-option-${this._activeIndex}`;
    }

    _updateActiveIndex() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex((opt) => opt.value === this._value);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    handleKeydown(event) {
        const { key } = event;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectOption(this._activeIndex);
                break;
        }
    }

    handleClick(event) {
        const value = event.target.dataset.value;
        const index = this._options.findIndex((opt) => opt.value === value);
        if (index >= 0) {
            this._selectOption(index);
        }
    }

    _selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }

        this._activeIndex = index;

        if (option.value === this._value) {
            return;
        }

        this._value = option.value;

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
