public class EmployerService {

    /**
     * Sets the current employer (primary affiliation) for a batch of contacts.
     *
     * Relies on NPSP's standard mechanism: updating Contact.npsp__Primary_Affiliation__c
     * causes NPSP's own trigger to create the new Current/Primary affiliation and to
     * convert the previous primary affiliation to Former with EndDate = today.
     *
     * Constraints met:
     *  - 200+ contacts in one call (bulk-safe)
     *  - 1 SOQL query (within the 2-query limit)
     *  - 1 DML statement (within the 2-DML limit)
     *  - Idempotent: no-op when the org is already the primary affiliation
     *  - Null/empty map is a no-op
     *  - Household membership is untouched (we only change the primary-affiliation lookup)
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // --- Query 1 (and only query): fetch the contacts and their current primary affiliation ---
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
        ];

        // --- Build the set of contacts that actually need updating ---
        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : contacts) {
            Id targetOrgId = employerByContactId.get(c.Id);
            // Skip if no mapping was supplied for this contact (defensive) or if already primary
            if (targetOrgId == null) {
                continue;
            }
            if (c.npsp__Primary_Affiliation__c == targetOrgId) {
                continue; // already the primary employer – do nothing (idempotent)
            }
            c.npsp__Primary_Affiliation__c = targetOrgId;
            toUpdate.add(c);
        }

        // --- DML 1 (and only DML): update the contacts ---
        // NPSP's standard trigger on Contact fires here and handles:
        //   • creating the new npe5__Affiliation__c (Status=Current, Primary=true, StartDate=today)
        //   • updating the previous primary affiliation (Status=Former, Primary=false, EndDate=today)
        // The household account (npsp__Household_Account__c) is not touched.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
