public class AccountOwnershipService {

    /**
     * Reassigns ownership of the specified Accounts and all of their Contacts to newOwnerId.
     *
     * - Account trigger actions are bypassed for the duration of the Account DML (TAF transaction
     *   bypass for the whole sObject) and are cleared in a finally block so that Account automation
     *   resumes normally even if this method throws.
     * - Contact trigger actions are unaffected and run normally.
     * - At most two SOQL queries and two DML statements are issued regardless of volume.
     * - Exceptions from DML propagate to the caller unchanged (all-or-none within the transaction).
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Schema.SObjectType accountType = Schema.getGlobalDescribe().get('Account');

        // Bypass ALL Account trigger actions for the duration of this method.
        TriggerBase.bypass(accountType);

        try {
            // Query 1 of 2 – fetch the target Accounts.
            List<Account> accounts = [
                SELECT Id
                FROM Account
                WHERE Id IN :accountIds
            ];

            for (Account acc : accounts) {
                acc.OwnerId = newOwnerId;
            }

            // DML 1 of 2 – update Accounts (trigger actions bypassed).
            update accounts;

            // Query 2 of 2 – fetch all Contacts belonging to those Accounts.
            List<Contact> contacts = [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
            ];

            for (Contact con : contacts) {
                con.OwnerId = newOwnerId;
            }

            // DML 2 of 2 – update Contacts (trigger actions run normally).
            update contacts;

        } finally {
            // Always clear the Account bypass so that Account automation
            // behaves normally for the remainder of the transaction,
            // whether this method succeeded or threw.
            TriggerBase.clearBypass(accountType);
        }
    }
}
