public class AccountOwnershipService {

    /**
     * Reassigns the given Accounts and all their Contacts to newOwnerId.
     *
     * - Account trigger actions are bypassed for the duration of the Account DML
     *   (TAF transaction bypass) and restored immediately afterwards.
     * - Contact trigger actions run normally.
     * - All-or-none: both updates are in the same transaction; any exception
     *   propagates unchanged to the caller.
     * - Bulk-safe: 2 SOQL queries and at most 2 DML statements regardless of volume.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // --- Query (1 of 2): target Accounts ---
        List<Account> accounts =
            [SELECT Id FROM Account WHERE Id IN :accountIds];

        for (Account acc : accounts) {
            acc.OwnerId = newOwnerId;
        }

        // --- Query (2 of 2): all Contacts belonging to those Accounts ---
        List<Contact> contacts =
            [SELECT Id FROM Contact WHERE AccountId IN :accountIds];

        for (Contact con : contacts) {
            con.OwnerId = newOwnerId;
        }

        // Bypass all Account trigger actions for this sObject in the current
        // transaction so the expensive territory-recalculation actions do not fire.
        TriggerBase.bypass('Account');
        try {
            // --- DML (1 of 2): update Accounts (trigger actions suppressed) ---
            update accounts;

            // --- DML (2 of 2): update Contacts (trigger actions run normally) ---
            if (!contacts.isEmpty()) {
                update contacts;
            }
        } finally {
            // Restore Account automation for the remainder of the transaction,
            // whether the DML succeeded or an exception is propagating.
            TriggerBase.clearBypass('Account');
        }
    }
}
