public class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MSG =
            'Another contact on this account already uses this email address.';

    // ------------------------------------------------------------------
    // Before Insert
    // ------------------------------------------------------------------
    public void beforeInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        // Collect eligible contacts (must have both AccountId and a non-blank Email)
        List<Contact> eligible = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                eligible.add(c);
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Single SOQL: existing contacts sharing any of the relevant AccountIds
        Map<String, Set<Id>> dbEmails = new Map<String, Set<Id>>();
        for (Contact existing : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email != null
                  AND Email != ''
                  AND AccountId != null
        ]) {
            String key = existing.AccountId + '|' + existing.Email.toLowerCase();
            if (!dbEmails.containsKey(key)) {
                dbEmails.put(key, new Set<Id>());
            }
            dbEmails.get(key).add(existing.Id);
        }

        // Walk in order; first occurrence of a key is accepted, later ones rejected
        Set<String> seenInBatch = new Set<String>();

        for (Contact c : eligible) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();
            Boolean conflict = dbEmails.containsKey(key) || seenInBatch.contains(key);

            if (conflict) {
                c.addError(ERROR_MSG);
            } else {
                seenInBatch.add(key);
            }
        }
    }

    // ------------------------------------------------------------------
    // Before Update
    // ------------------------------------------------------------------
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        // Only contacts whose Email or AccountId actually changed are candidates
        List<Contact> eligible = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<Id> updatingIds = new Set<Id>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact c = (Contact) triggerNew[i];
            Contact old = (Contact) triggerOld[i];

            if (c.AccountId != null
                    && String.isNotBlank(c.Email)
                    && (c.Email != old.Email || c.AccountId != old.AccountId)) {
                eligible.add(c);
                accountIds.add(c.AccountId);
                updatingIds.add(c.Id);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Single SOQL: existing contacts on those accounts, excluding the records
        // currently being updated (a contact never conflicts with itself)
        Map<String, Set<Id>> dbEmails = new Map<String, Set<Id>>();
        for (Contact existing : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email != null
                  AND Email != ''
                  AND AccountId != null
                  AND Id NOT IN :updatingIds
        ]) {
            String key = existing.AccountId + '|' + existing.Email.toLowerCase();
            if (!dbEmails.containsKey(key)) {
                dbEmails.put(key, new Set<Id>());
            }
            dbEmails.get(key).add(existing.Id);
        }

        // Walk in order; first occurrence of a key is accepted, later ones rejected
        Set<String> seenInBatch = new Set<String>();

        for (Contact c : eligible) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();
            Boolean conflict = dbEmails.containsKey(key) || seenInBatch.contains(key);

            if (conflict) {
                c.addError(ERROR_MSG);
            } else {
                seenInBatch.add(key);
            }
        }
    }
}
