public class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MSG =
        'Another contact on this account already uses this email address.';

    // ── Before Insert ──────────────────────────────────────────────────────────

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;

        List<Contact> toCheck = new List<Contact>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                toCheck.add(c);
            }
        }

        if (toCheck.isEmpty()) {
            return;
        }

        enforceRule(toCheck, null);
    }

    // ── Before Update ──────────────────────────────────────────────────────────

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;

        List<Contact> toCheck   = new List<Contact>();
        Set<Id>    excludeIds  = new Set<Id>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];
            Contact o = oldContacts[i];

            // Only check when Email or AccountId actually changed
            if (c.Email != o.Email || c.AccountId != o.AccountId) {
                if (c.AccountId != null && String.isNotBlank(c.Email)) {
                    toCheck.add(c);
                    excludeIds.add(c.Id);   // never conflict with itself
                }
            }
        }

        if (toCheck.isEmpty()) {
            return;
        }

        enforceRule(toCheck, excludeIds);
    }

    // ── Core enforcement (single SOQL) ─────────────────────────────────────────

    private void enforceRule(List<Contact> toCheck, Set<Id> excludeIds) {
        // Collect the set of Account Ids we need to check
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : toCheck) {
            accountIds.add(c.AccountId);
        }

        // Build the set of (accountId|lowercasedEmail) already occupied
        Set<String> usedKeys = new Set<String>();

        List<Contact> existing = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        for (Contact c : existing) {
            // Exclude contacts currently being updated so they don't
            // conflict with their own stale DB row.
            if (excludeIds != null && excludeIds.contains(c.Id)) {
                continue;
            }
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                usedKeys.add(c.AccountId + '|' + c.Email.toLowerCase());
            }
        }

        // Walk the batch in order: first contact that "claims" a key wins,
        // every later contact with the same key is rejected.
        for (Contact c : toCheck) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();
            if (usedKeys.contains(key)) {
                c.addError(ERROR_MSG);
            } else {
                usedKeys.add(key);
            }
        }
    }
}
```

