            t.beforeUpdate(Trigger.new, Trigger.old);
        } else if (Trigger.isDelete) {
            t.beforeDelete(Trigger.old);
        }
    } else if (Trigger.isAfter) {
        if (Trigger.isInsert) {
            t.afterInsert(Trigger.new);
        } else if (Trigger.isUpdate) {
            t.afterUpdate(Trigger.new, Trigger.old);
        } else if (Trigger.isDelete) {
            t.afterDelete(Trigger.old);
        } else if (Trigger.isUndelete) {
            t.afterUndelete(Trigger.new);
        }
    }
}
