public class TA_Case_AddClosureComment implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        List<CaseComment> comments = new List<CaseComment>();
        String dateStr = String.valueOf(Date.today());
        for (SObject so : triggerNew) {
            Case c = (Case) so;
            Case old = (Case) oldMap.get(c.Id);
            if (c.Status == 'Closed' && old.Status != 'Closed') {
                comments.add(new CaseComment(
                    ParentId = c.Id,
                    CommentBody = 'Case closed on ' + dateStr,
                    IsPublished = false
                ));
            }
        }
        if (!comments.isEmpty()) {
            insert comments;
        }
    }
}
