File: force-app/main/default/classes/TA_Opportunity_LogAmountChange.cls
```apex
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    /**
     * Creates a "Amount changed" audit Task for each Opportunity whose Amount
     * differs between old and new, but only on the first trigger pass of the
     * transaction.  Subsequent passes (e.g. the recursive update performed by
     * TA_Opportunity_RoundAmount, Order 20) are skipped so that at most one
     * task is produced per opportunity per transaction.
     */
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {

        // Index the old records for O(1) lookup
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        for (Opportunity oldOpp : triggerOld) {
            oldById.put(oldOpp.Id, oldOpp);
        }

        List<Task> tasksToCreate = new List<Task>();

        for (Opportunity opp : triggerNew) {
            // Recursion guard: skip if this record has already been seen in a
            // prior after-update pass within the same transaction (i.e. the
            // second pass fired by the rounding DML).
            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(opp.Id);
            if (timesSeen != null && timesSeen > 1) {
                continue;
            }

            Opportunity oldOpp = oldById.get(opp.Id);
            if (oldOpp == null) {
                continue;
            }

            // Only log when Amount actually changed
            if (oldOpp.Amount != opp.Amount) {
                tasksToCreate.add(new Task(
                    Subject  = 'Amount changed',
                    WhatId   = opp.Id,
                    Status   = 'Completed'
                ));
            }
        }

        // Single bulk DML – one insert per trigger execution
        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }
    }
}
